            local frame=create("VideoFrame",{Name="VideoProbeFrame",Size=UDim2.fromScale(1,1),BackgroundTransparency=1,Visible=true,Volume=0,Looped=true,Playing=false},videoHost)
            P.frame=frame
            pcall(function()
                P.logConnection=logs.MessageOut:Connect(function(message)
                    if generation~=P.generation or P.current~=current or type(message)~="string" or not message:find(source,1,true) then return end
                    local lower=message:lower()
                    if lower:find("fail",1,true) or lower:find("error",1,true) then current.nativeError=scrub(message,source) end
                end)
            end)
            -- Both controls use the same visible, parented native player.
            P.startedAt=os.clock();frame.Video=source;frame:Play()
        end)
        if not ok and P.alive and generation==P.generation then P.EndCase(false,"prepare",err) end
    end)
end
function P.Step()
    local frame,current=P.frame,P.current
    if not P.alive or not current then return end
    if not frame then
        if os.clock()-P.caseStartedAt>=15 then P.EndCase(false,"prepareTimeout") end
        return
    end
    if frame.IsLoaded then
        if P.timeBase==nil then P.timeBase=frame.TimePosition
        elseif math.abs(frame.TimePosition-P.timeBase)>.02 then P.EndCase(true,"mediaTimeAdvanced");return end
    end
    if os.clock()-P.caseStartedAt>=15 then P.EndCase(false,frame.IsLoaded and "loadedWithoutProgress" or "loadTimeout") end
end
function P.Start()
    local elapsed=0
    P.watch=Run.Heartbeat:Connect(function(dt)
        elapsed=elapsed+dt;if elapsed<.1 then return end;elapsed=0
        local ok,err=pcall(P.Step)
        if not ok then P.EndCase(false,"readback",err) end
    end)
    P.StartCase(1)
end
-- END comparison controller
function P.DestroyUI() gui:Destroy() end
connect(gui.Destroying,function() if P.alive then P.Stop() end end)
connect(close.Activated,P.Stop)
connect(copy.Activated,function()
    if P.result.running then P.Status("O teste ainda esta em andamento. Aguarde o resultado dos dois videos.");return end
    local text=Http:JSONEncode(P.result)
    if type(setclipboard)=="function" then
        local ok=pcall(setclipboard,text)
        if ok then P.Status("Resultado copiado. Envie no chat.");return end
    end
    export.Text=text;export.Visible=true
    P.Status("Selecione o texto abaixo para copiar o resultado.")
end)
P.Start()
return P
